**bounceBrick** (new export):

```js
// Resolves one overlap between the ball and one brick. `collides()` only says
// WHETHER the ball overlaps; this decides WHICH face (or corner) was hit from
// the penetration depths, flips the corresponding velocity component(s) and
// pushes the ball back out of the brick (no sticky re-collision on the next
// frame).
//
// Axis rule: the touched axis is the one with the smallest penetration; when
// the ball center is off a corner (outside both spans), both components
// invert. The `flipped` guard caps the resolution at one inversion per axis
// and per pass, so two bricks sharing a seam can never double-invert the same
// component back to its original sign.
export function bounceBrick(ball, brick, flipped = { x: false, y: false }) {
  // Penetration through each of the four faces (all >= 0 while overlapping).
  const penTop = ball.y + ball.r - brick.y;
  const penBottom = brick.y + brick.h - (ball.y - ball.r);
  const penLeft = ball.x + ball.r - brick.x;
  const penRight = brick.x + brick.w - (ball.x - ball.r);

  // Is the ball center outside both spans? Then it is off a corner.
  const outsideX = ball.x < brick.x || ball.x > brick.x + brick.w;
  const outsideY = ball.y < brick.y || ball.y > brick.y + brick.h;

  if (outsideX && outsideY) {
    // Corner hit: both axes invert, push out along the diagonal.
    if (!flipped.x) {
      ball.vx = -ball.vx;
      flipped.x = true;
    }
    if (!flipped.y) {
      ball.vy = -ball.vy;
      flipped.y = true;
    }
    ball.x = ball.x < brick.x ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.y = ball.y < brick.y ? brick.y - ball.r : brick.y + brick.h + ball.r;
  } else if (Math.min(penLeft, penRight) <= Math.min(penTop, penBottom)) {
    // Side face: invert vx (once per pass), push out sideways.
    if (!flipped.x) {
      ball.vx = -ball.vx;
      flipped.x = true;
    }
    ball.x = penLeft < penRight ? brick.x - ball.r : brick.x + brick.w + ball.r;
  } else {
    // Top or bottom face: invert vy (once per pass), push out vertically.
    if (!flipped.y) {
      ball.vy = -ball.vy;
