```js
export function step(state, dt) {
  const { ball, paddle, bricks } = state;
  const speed = ballSpeed(state.level);

  // Swept collision: split the move into substeps short enough that no
  // obstacle can be crossed between two checks. The thinnest obstacle is a
  // brick (BRICK_H = 20); 10 px per substep leaves a safe margin, so a ball
  // moving at max speed (level 6: 35.5 px/frame) can never skip one.
  const distance = Math.hypot(ball.vx, ball.vy) * dt;
  const subSteps = Math.max(1, Math.ceil(distance / 10));
  const subDt = dt / subSteps;

  // One inversion per axis and per frame: two bricks sharing a seam must not
  // double-invert the same component back to its original sign.
  const flipped = { x: false, y: false };

  for (let i = 0; i < subSteps; i++) {
    const prevX = ball.x;
    const prevY = ball.y;
    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Bricks: bounce, destroy, score.
    for (const brick of bricks) {
      if (!brick.alive) continue;
      if (collides(ball, brick)) {
        bounceBrick(ball, brick, flipped);
        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
      }
    }

    // Paddle: bounce iff the ball's bottom crossed the paddle top during this
    // substep (swept, so a fast ball can't skip the 12 px band) or the paddle
    // was teleported onto the ball (mouse) — the ball always exits through the
    // top, never through a side or the bottom.
    const bottomCrossed =
      prevY + ball.r <= paddle.y && ball.y + ball.r >= paddle.y;
    const overPaddleX =
      ball.x + ball.r > paddle.x && ball.x - ball.r < paddle.x + paddle.w;
    const insidePaddle =
      ball.y + ball.r >= paddle.y &&
      ball.y - ball.r <= paddle.y + paddle.h &&
      overPaddleX;
    if ((bottomCrossed && overPaddleX) || insidePaddle) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      // Rebound direction: hit in [-1, 1], floored so a dead-center hit keeps
      // a playable horizontal component (no perpetual straight-up trajectory),
      // then normalized so the speed after the bounce is exactly the level's.
      let dirX = 0.6 * hit;
      if (dirX === 0) dirX = 0.15;
      else if (Math.abs(dirX) < 0.15) dirX = Math.sign(dirX) * 0.15;
      const norm = Math.hypot(dirX, 1);
      ball.vx = (speed * dirX) / norm;
      ball.vy = -(speed / norm);
      state.combo = 0; // touching the paddle resets the combo
    }
  }

  // Exit through the bottom: ball lost.
  return ball.y - ball.r > HEIGHT;
}
