// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// --- Brick collisions ------------------------------------------------------

// D1: the reported symptom — a ball plowing into a brick must bounce, not
// pass through. The brick is destroyed, vy flips UP on a top-face hit and the
// ball is pushed back out of the rectangle (no sticky re-collision next frame).
test('step: ball bounces off the top face of a brick and is pushed out', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // row 0, col 0: (4,48) 72x20
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - BALL_R - 1, r: BALL_R, vx: 0, vy: 300 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, false);
  assert.equal(brick.alive, false, 'the hit brick is destroyed');
  assert.ok(state.ball.vy < 0, 'vy flips UP after a top-face hit');
  assert.ok(state.ball.y + state.ball.r <= brick.y, 'ball is pushed back out above the brick');
});

// D1: same on a side face — vx flips LEFT and the ball exits through the side.
test('step: ball bounces off the side face of a brick', () => {
  const state = createState(1);
  const brick = state.bricks[1]; // row 0, col 1: (84,48) 72x20
  state.ball = { x: brick.x - 3, y: brick.y + 10, r: BALL_R, vx: 300, vy: 0 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, false);
  assert.equal(brick.alive, false, 'the hit brick is destroyed');
  assert.ok(state.ball.vx < 0, 'vx flips LEFT after a left-face hit');
  assert.ok(state.ball.x + state.ball.r <= brick.x, 'ball is pushed back out left of the brick');
});

// D3: a corner hit (ball center outside both spans, equal penetrations)
// inverts BOTH components and pushes the ball out along the diagonal.
test('step: corner hit inverts both components', () => {
  const state = createState(1);
  const brick = state.bricks[1]; // (84,48)
  state.ball = { x: brick.x - 2, y: brick.y - 2, r: BALL_R, vx: 60, vy: 60 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, false);
  assert.equal(brick.alive, false, 'the hit brick is destroyed');
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'both components invert at a corner');
  assert.ok(
    state.ball.x + state.ball.r <= brick.x && state.ball.y + state.ball.r <= brick.y,
    'ball is pushed out along the diagonal',
  );
});

// D4: the seam between two stacked bricks (gap 8 < ball diameter 14) lets the
// ball overlap both in one pass. Two vy flips would cancel out and the ball
// would keep falling — exactly one flip per axis and per pass must happen.
test('step: seam between two stacked bricks does not double-invert vy', () => {
  const state = createState(1);
  const top = state.bricks[0]; // row 0: y 48..68
  const bottom = state.bricks[8]; // row 1: y 76..96
  assert.equal(bottom.y - (top.y + top.h), 8, 'fixture: stacked bricks, 8px gap');
  state.ball = { x: top.x + top.w / 2, y: top.y + top.h + 4, r: BALL_R, vx: 0, vy: 100 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, false);
  assert.equal(top.alive, false);
  assert.equal(bottom.alive, false);
  assert.ok(state.ball.vy < 0, 'vy flips exactly once: still UP after the seam');
});

// D5: tunneling. Level 6: ballSpeed = 710, one 50ms step covers 35.5px, more
// than BRICK_H + 2*BALL_R = 34. A discrete check would skip the brick entirely.
test('step: no brick is tunneled through at max speed (level 6, dt=50ms)', () => {
  const state = createState(6);
  const brick = state.bricks[0]; // (4,48)
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(6) };
  const lost = step(state, 0.05);
  assert.equal(lost, false);
  assert.equal(brick.alive, false, 'the fast ball still hits the brick');
  assert.ok(state.ball.vy < 0, 'and bounces back up');
});

// D9: the bounce decision must not depend on the frame rate.
test('step: brick bounce decision is independent of the frame rate', () => {
  const run = (dt) => {
    const state = createState(6);
    const brick = state.bricks[0];
    state.ball = { x: brick.x + brick.w / 2, y: brick.y - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(6) };
    step(state, dt);
    return { alive: brick.alive, vy: state.ball.vy };
  };
  const at30 = run(1 / 30);
  const at144 = run(1 / 144);
  assert.equal(at30.alive, false, 'brick hit at 30 fps');
  assert.equal(at144.alive, false, 'brick hit at 144 fps');
  assert.equal(Math.sign(at30.vy), Math.sign(at144.vy), 'same bounce decision at both rates');
  assert.ok(at30.vy < 0 && at144.vy < 0);
});

// --- Paddle ----------------------------------------------------------------

// D6: a fast ball must not skip the 12px paddle band between two checks.
test('step: fast ball cannot tunnel through the paddle from above', () => {
  const state = createState(6);
  state.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: 0, vy: ballSpeed(6) };
  const lost = step(state, 0.05);
  assert.equal(lost, false, 'the ball must not be lost');
  assert.ok(state.ball.vy < 0, 'the ball bounces back up off the paddle');
  assert.ok(state.ball.y + state.ball.r <= PADDLE_Y, 'the ball exits through the top of the paddle');
});

// D7: the paddle follows the mouse — if it is teleported onto the ball, the
// ball must still come out through the top, not be captured.
test('step: paddle teleported onto the ball pushes it back out through the top', () => {
  const state = createState(1);
  state.ball = { x: WIDTH / 2, y: PADDLE_Y + 5, r: BALL_R, vx: 0, vy: 200 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, false);
  assert.ok(state.ball.vy < 0);
  assert.ok(state.ball.y + state.ball.r <= PADDLE_Y);
});

// D8: the rebound must conserve the level speed, keep a playable horizontal
// component even on a dead-center hit, and reset the combo.
test('step: paddle rebound keeps the level speed and never a dead-straight shot', () => {
  const state = createState(1);
  state.combo = 3;
  state.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 3, r: BALL_R, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, false);
  assert.notEqual(state.ball.vx, 0, 'a dead-center hit still gets a horizontal component');
  assert.ok(state.ball.vy < 0);
  assert.ok(
    Math.abs(Math.hypot(state.ball.vx, state.ball.vy) - ballSpeed(1)) < 1e-9,
    'speed after the paddle bounce equals the level speed',
  );
  assert.equal(state.combo, 0, 'touching the paddle resets the combo');
});

// --- Score (logic moved from frame() into step()) --------------------------

// Regression: a brick is scored exactly once, combo bumps by one.
test('step: breaking a brick scores it exactly once and bumps the combo', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - BALL_R - 1, r: BALL_R, vx: 0, vy: 300 };
  step(state, 1 / 60);
  assert.equal(state.score, 75, 'row-0 brick (50 pts) with combo 1 (x1.5)');
  assert.equal(state.combo, 1);
});

